#!/usr/bin/env python3
"""Idempotent installer for increment 1 (model-relative domain validator).

Run from the HEPLocalAgent repo root:  python apply_increment_1.py
Safe to run repeatedly. Does not use git; only writes/edits files, then tests.
"""
import base64, pathlib, subprocess, sys

MOD_B64 = ''
TST_B64 = ''
ANCHOR = '    try:\n        build_madgraph_artifact(workflow)\n    except MadGraphBuildError as exc:\n        issues.append(\n            ValidationIssue(\n                code="builder_rejected_workflow",'
INSERT = '    # Model-relative domain validation: reject particle or multiparticle\n    # tokens that do not exist in the selected model before any artifact is\n    # built or executed. Imported locally to avoid an import cycle at module\n    # load time (model_domain imports the issue types from this module).\n    from hep_agent.validation.model_domain import validate_model_domain\n\n    issues.extend(validate_model_domain(workflow).issues)\n\n    try:\n        build_madgraph_artifact(workflow)\n    except MadGraphBuildError as exc:\n        issues.append(\n            ValidationIssue(\n                code="builder_rejected_workflow",'

def die(msg): print("ERROR:", msg); raise SystemExit(1)

root = pathlib.Path(".")
if not (root / "pyproject.toml").is_file() or "hep-local-agent" not in (root/"pyproject.toml").read_text():
    die("Run this from the HEPLocalAgent repository root.")

def write(rel, b64):
    p = root / rel
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_bytes(base64.b64decode(b64))
    print("wrote  ", rel)

write("src/hep_agent/validation/model_domain.py", MOD_B64)
write("tests/test_model_domain_validation.py", TST_B64)

core = root / "src/hep_agent/validation/core.py"
t = core.read_text()
if "validate_model_domain" in t:
    print("core.py: already wired")
elif ANCHOR in t:
    core.write_text(t.replace(ANCHOR, INSERT, 1))
    print("core.py: wired the domain check")
else:
    die("core.py anchor not found - your core.py differs from 878b69b. Stop and tell me.")

init = root / "src/hep_agent/validation/__init__.py"
it = init.read_text()
if "model_domain" not in it:
    needle = "from .madgraph_workflow import (\n    validate_madgraph_workflow_artifact,\n)"
    if needle in it:
        add = needle + "\nfrom .model_domain import (\n    ModelNamespace,\n    namespace_for_model,\n    validate_model_domain,\n)"
        init.write_text(it.replace(needle, add, 1))
        print("__init__.py: added exports")
    else:
        print("__init__.py: export anchor not found (non-fatal; tests import the submodule directly)")
else:
    print("__init__.py: already has exports")

print("\nRunning the test suite...\n")
sys.exit(subprocess.call([sys.executable, "-m", "unittest", "discover", "-s", "tests", "-p", "test_*.py"]))
